def replace_questions_without_repeats(s):
 chars=list(s)
 for index,char in enumerate(chars):
  if char=='?':
   for choice in 'abc':
    if (index==0 or chars[index-1]!=choice) and (index+1==len(chars) or chars[index+1]!=choice):chars[index]=choice;break
 return ''.join(chars)

